def filtrar_tecnico(df, tecnico, coluna='Técnico'):
    if df is None or len(df) == 0 or tecnico == 'Todos os técnicos' or coluna not in df.columns:
        return df
    return df[df[coluna].astype(str) == tecnico].copy()


def preparar_resumos(det):
    if det is None or len(det) == 0:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
    por_tecnico = det.groupby('Técnico', as_index=False).agg(
        OS=('OS','count'), Horas=('Horas Pagas','sum'), Valor=('Valor Total','sum')
    ).sort_values('Valor', ascending=False)
    por_cliente = det.groupby('Cliente', as_index=False).agg(
        OS=('OS','count'), Valor=('Valor Total','sum')
    ).sort_values('Valor', ascending=False)
    por_tipo = det.groupby('Tipo OS', as_index=False).agg(
        OS=('OS','count'), Valor=('Valor Total','sum')
    ).sort_values('Valor', ascending=False)
    return por_tecnico, por_cliente, por_tipo


