def _historico_para_detalhe(df):
    if df is None or df.empty:
        return pd.DataFrame()
    ren = {
        'linha_origem':'linha_origem','os':'OS','cliente':'Cliente','tecnico':'Técnico',
        'tipo_os':'Tipo OS','data':'Data','inicio':'Início','termino':'Término',
        'tempo_minutos':'Tempo minutos','horas_pagas':'Horas Pagas','regra':'Regra',
        'valor_primeira':'Valor 1ª Hora','valor_adicional':'Valor Hora Adicional',
        'valor_total':'Valor Total','centro_custo':'Centro de Custo',
        'plantao_fds':'Plantão FDS','faixa_plantao':'Faixa Plantão',
        'fim_de_semana':'Fim de Semana','status':'Status',
        'tipo_original':'Tipo Original','tipo_pagamento':'Tipo Pagamento',
        'valor_mao_obra':'Valor Mão de Obra','quilometragem':'Quilometragem',
        'pedagio':'Pedágio','outros_ajustes':'Outros Ajustes',
        'justificativa_ajuste':'Justificativa Ajuste','origem_valor':'Origem do Valor',
    }
    out = df.rename(columns=ren).copy()
    if 'Plantão FDS' in out:
        out['Plantão FDS'] = pd.to_numeric(out['Plantão FDS'], errors='coerce').fillna(0).astype(int).astype(bool)
    return out


def _historico_para_pendencias(df):
    if df is None or df.empty:
        return pd.DataFrame()
    return df.rename(columns={
        'linha_origem':'linha_origem','os':'OS','cliente':'Cliente','tecnico':'Técnico',
        'tipo_os':'Tipo OS','centro_custo':'Centro de Custo','motivo':'Motivo','status':'Status',
    }).copy()


def _conferencia_do_meta(meta):
    try:
        checks = json.loads(meta.get('checks_json') or '[]')
    except Exception:
        checks = []
    try:
        alertas = json.loads(meta.get('alertas_json') or '[]')
    except Exception:
        alertas = []
    return {
        'aprovavel': bool(meta.get('aprovavel')),
        'total': float(meta.get('total') or 0),
        'checks': checks,
        'alertas': alertas,
    }

