        # Se o período corresponde a uma única competência/apuração, restauramos também
        # aprovação e arquivo original. Em um intervalo multi-competência, o dashboard é consolidado.
        if len(hist_periodo) == 1:
            meta = hist_periodo.iloc[0].to_dict()
            st.session_state['conferencia'] = _conferencia_do_meta(meta)
            st.session_state['apuracao_id'] = meta.get('id')
