def bloco_importacao():
    st.markdown('<div class="section-title">Carregar nova apuração</div>', unsafe_allow_html=True)
    a,b = st.columns(2)
    with a:
        man_file = st.file_uploader('Relatório de manutenções', type=['xlsx','xls','csv'], key='manutencoes_v7')
    with b:
        param_file = st.file_uploader('Parametrização de custos (opcional)', type=['xlsx','xls','csv'], key='parametrizacao_v7')

    if man_file:
        try:
            man, _ = ler_relatorio(man_file)
            mapa = mapear_colunas(man)
            obrig = ['tecnico','tipo_os','data','inicio','fim','centro_custo']
            falt = [c for c in obrig if c not in mapa]
            if falt:
                cols_norm = {str(c).strip().upper() for c in man.columns}
                if {'SEGUIMENTO','VALOR 1º HORA','VALOR H_ADCIONAL'}.issubset(cols_norm):
                    st.error('O primeiro arquivo parece ser a planilha de custos. Carregue o relatório de atendimentos.')
                else:
                    st.error('Arquivo incompatível. Não foi possível localizar com segurança: ' + ', '.join(falt))
                return

            param = None
            if param_file:
                param_raw = ler_parametrizacao(param_file)
                if parece_relatorio_em_vez_de_parametrizacao(param_raw):
                    st.error('O arquivo de parametrização parece ser um relatório de OS.')
                    return
                param = preparar_parametrizacao(param_raw)
            if param is None:
                param = criar_parametrizacao_padrao(man[mapa['tecnico']].dropna().tolist())

            feriados=[]
            for linha in feriados_txt.splitlines():
                if linha.strip():
                    feriados.append(datetime.strptime(linha.strip(), '%d/%m/%Y').date())

            if st.button('PROCESSAR E VALIDAR APURAÇÃO', type='primary', use_container_width=True):
                det, pend = processar(man, param, mapa, hc_ini, hc_fim, feriados, permitir_virada_dia=permitir_virada)
                # Enriquecimento é persistido no banco a partir da V7.
                det = enriquecer_plantao(det).drop(columns=['_dt_inicio','_dt_fim'], errors='ignore')
                conferencia = executar_conferencias(det, pend, len(man))
                if len(det) == 0:
                    # Mesmo com 100% das linhas pendentes, preserva a fonte na sessão
                    # para permitir correção diretamente na grade de Conferência.
                    st.session_state.update({
                        'det':det, 'pend':pend, 'param_usada':param,
                        'conferencia':conferencia, 'apuracao_id':None,
                        'carregado_historico':False, 'aprovada_agora':False,
                        'arquivo_original_bytes': man_file.getvalue() if hasattr(man_file, 'getvalue') else None,
                        'arquivo_original_nome': getattr(man_file, 'name', 'relatorio.xlsx'),
                        'fonte_man_v107': man.copy(),
                        'fonte_mapa_v107': dict(mapa),
                        'fonte_param_v107': param.copy(),
                        'fonte_hc_ini_v107': hc_ini,
                        'fonte_hc_fim_v107': hc_fim,
                        'fonte_feriados_v107': list(feriados),
                        'fonte_virada_v107': permitir_virada,
                        'periodo_dados_chave': periodo_chave,
                    })
                    motivos = pend['Motivo'].value_counts().to_dict() if len(pend) and 'Motivo' in pend.columns else {}
                    st.error(f'0 OS processadas. Corrija as pendências diretamente em Conferência. Pendências: {motivos}')
                    st.stop()
                # A competência da nova apuração é inferida pela data mais recente do próprio relatório.
                datas_validas = pd.to_datetime(det.get('Data', pd.Series(dtype='datetime64[ns]')), errors='coerce').dropna()
                competencia_arquivo = datas_validas.max().strftime('%m/%Y') if len(datas_validas) else data_fim.strftime('%m/%Y')
                ap_id = salvar_apuracao(
                    det, pend, conferencia,
                    arquivo_origem=getattr(man_file, 'name', ''),
                    competencia=competencia_arquivo,
                    arquivo_original_bytes=man_file.getvalue() if hasattr(man_file, 'getvalue') else None,
                )
                st.session_state.update({
                    'det':det, 'pend':pend, 'param_usada':param,
                    'periodo_dados_chave': periodo_chave,
                    'carregado_historico': False,
                    'conferencia':conferencia, 'apuracao_id':ap_id,
                    'aprovada_agora':False,
                    'arquivo_original_bytes': man_file.getvalue() if hasattr(man_file, 'getvalue') else None,
                    'arquivo_original_nome': getattr(man_file, 'name', 'relatorio.xlsx'),
                    'fonte_man_v107': man.copy(),
                    'fonte_mapa_v107': dict(mapa),
                    'fonte_param_v107': param.copy(),
                    'fonte_hc_ini_v107': hc_ini,
                    'fonte_hc_fim_v107': hc_fim,
                    'fonte_feriados_v107': list(feriados),
                    'fonte_virada_v107': permitir_virada,
                })
                st.rerun()
        except Exception as exc:
            st.error('Falha ao processar o arquivo. Nenhum pagamento foi aprovado.')
            st.exception(exc)


