    hist_all = listar_apuracoes()

    def _competencia_anterior(dt_ref):
        primeiro = pd.Timestamp(dt_ref.year, dt_ref.month, 1)
        anterior = primeiro - pd.offsets.MonthBegin(1)
        return anterior.strftime('%m/%Y')

    def _nota_comparativa(atual, anterior, formato='numero'):
        if anterior is None:
            return '<span style="color:#7b8797">Sem período anterior para comparação</span>'
        try:
            a=float(atual); b=float(anterior)
        except Exception:
            return '<span style="color:#7b8797">Sem período anterior para comparação</span>'
        if b == 0:
            if a == 0:
                return '<span style="color:#7b8797;font-weight:700">sem variação</span><br><span>vs. período anterior</span>'
            return '<span style="color:#7b8797">Sem base anterior para percentual</span>'
        variacao=(a-b)/b*100.0
        if abs(variacao) < 0.05:
            destaque='<span style="color:#7b8797;font-weight:800">→ 0,0%</span>'
        elif variacao > 0:
            destaque=f'<span style="color:#169b55;font-weight:800">↑ {abs(variacao):.1f}%</span>'.replace('.', ',')
        else:
            destaque=f'<span style="color:#d92d20;font-weight:800">↓ {abs(variacao):.1f}%</span>'.replace('.', ',')
        if formato == 'moeda':
            base=moeda(b)
        else:
            base=f'{b:.0f}'
        return f'{destaque}<br><span>vs. período anterior ({base})</span>'

    ant_os=ant_total=ant_horas=ant_tecnicos=None
