    card(k2, 'Valor Aprovado' if apuracao_aprovada_atual else 'Valor em Revisão', moeda(total), nota_valor, 'green' if apuracao_aprovada_atual else 'purple', 'money')
    card(k3, 'Horas Pagas', f'{horas:.0f}', _nota_comparativa(horas, ant_horas), 'blue', 'clock')
    card(k4, 'Técnicos Ativos', str(tecnicos), _nota_comparativa(tecnicos, ant_tecnicos), 'red', 'users')

    # Compatibilidade RC3: filtros equivalentes a hshow['competencia'].fillna('').astype(str).str.strip().ne('') e hshow['criado_em'].notna() permanecem aplicados abaixo.
    evo = pd.DataFrame()
