        if conf:
            for chk in conf['checks']:
                st.markdown(f"<div class={'status-ok' if chk['ok'] else 'status-bad'}>{'✅' if chk['ok'] else '⛔'} <b>{chk['nome']}</b> — {chk['detalhe']}</div><div style='height:6px'></div>", unsafe_allow_html=True)
            for alerta in conf.get('alertas',[]): st.warning(alerta)

        st.markdown('<div class="section-title">Conferência e ajustes</div>', unsafe_allow_html=True)
        if len(pend_atual):
            st.warning('Use **Com pendência**. A coluna **Ação necessária** informa o que corrigir. Edite **Tipo para Pagamento, KM, Pedágio, Outros e Justificativa** diretamente na grade e clique em **RECALCULAR E VALIDAR**.')
        # RC4: usa o mesmo snapshot persistido validado no ato da aprovação.
        _det_ajustes = det_atual
        _apid_ajustes = st.session_state.get('apuracao_id')
        if _apid_ajustes:
            try:
                _, _det_persistido = validar_aprovacao_persistida(_apid_ajustes)
                if isinstance(_det_persistido, pd.DataFrame) and len(_det_persistido):
                    _det_ajustes = _det_persistido
            except Exception:
                _det_ajustes = det_atual
        _aj_sem_just = _det_ajustes[_det_ajustes.get('Origem do Valor', pd.Series(index=_det_ajustes.index,dtype=str)).fillna('AUTOMÁTICO').astype(str).str.upper().ne('AUTOMÁTICO') & _det_ajustes.get('Justificativa Ajuste', pd.Series(index=_det_ajustes.index,dtype=str)).fillna('').astype(str).str.strip().eq('')].copy() if len(_det_ajustes) else pd.DataFrame()
        if len(_aj_sem_just):
            _os_aj=', '.join(_aj_sem_just['OS'].astype(str).str.replace(r'\.0$','',regex=True).head(12).tolist())
            st.error(f'Ajustes que bloqueiam a aprovação: {_os_aj}. Selecione **Ajustes sem justificativa**, preencha a justificativa e clique em **RECALCULAR E VALIDAR**.')
        opcoes_filtro=['Todas',f'Ajustes sem justificativa ({len(_aj_sem_just)})',f'Com pendência ({len(pend_atual)})',f'Sem pendência ({len(det_atual)})']
        filtro_grade=st.radio('Exibir',opcoes_filtro,horizontal=True,key='filtro_grade_v107')
        man_src=st.session_state.get('fonte_man_v107')
        mapa_src=st.session_state.get('fonte_mapa_v107')
        param_src=st.session_state.get('fonte_param_v107')
        if man_src is None or mapa_src is None or param_src is None:
            st.error('Não foi possível recuperar o arquivo original arquivado desta apuração. Sem essa fonte, a grade permanece somente para leitura.')
            if filtro_grade.startswith('Com pendência'):
                st.dataframe(pend_atual,use_container_width=True,hide_index=True)
            elif filtro_grade.startswith('Sem pendência'):
                st.dataframe(det_atual,use_container_width=True,hide_index=True)
            else:
                st.dataframe(pd.concat([det_atual,pend_atual],ignore_index=True,sort=False),use_container_width=True,hide_index=True)
        else:
            grade=montar_grade(man_src,mapa_src,det_atual,pend_atual)
            _salva=st.session_state.get('grade_edicoes_v117')
            if isinstance(_salva,pd.DataFrame) and len(_salva):
                _s=_salva.set_index('linha_origem')
                _g=grade.set_index('linha_origem')
                for _li in _g.index.intersection(_s.index):
                    for _c in ['Data','Hora Início','Hora Fim','Tipo para Pagamento','KM','Pedágio','Outros','Justificativa']:
                        if _c in _s.columns:
                            _g.at[_li,_c]=_s.at[_li,_c]
                    if 'Mão de Obra' in _s.columns:
                        _g.at[_li,'Mão de Obra']=_s.at[_li,'Mão de Obra']
                grade=_g.reset_index()
            if filtro_grade.startswith('Ajustes sem justificativa'):
                _linhas_aj=set(pd.to_numeric(_aj_sem_just.get('linha_origem',pd.Series(dtype=float)),errors='coerce').dropna().astype(int).tolist())
                exib=grade[grade['linha_origem'].astype(int).isin(_linhas_aj)].copy()
            elif filtro_grade.startswith('Com pendência'):
                exib=grade[grade['Situação'].eq('PENDENTE')].copy()
            elif filtro_grade.startswith('Sem pendência'):
                exib=grade[~grade['Situação'].eq('PENDENTE')].copy()
            else:
                exib=grade.copy()
            tipos=list(BASE_HC.keys())+['PORTAO']
            try:
                with sqlite3.connect(DB_PATH) as _con:
                    _extras=[r[0] for r in _con.execute("SELECT descricao FROM tarifas WHERE ativo=1 ORDER BY descricao")]
                tipos=list(dict.fromkeys(tipos+_extras))
            except Exception:
                pass
            # V11.14: garante tipos reais no DataFrame FINAL entregue ao Streamlit.
            # Edições restauradas da sessão podem reintroduzir strings; por isso a conversão
            # precisa ocorrer depois do merge/filtro, imediatamente antes do data_editor.
            exib=exib.copy()
            exib['Data']=pd.to_datetime(exib['Data'],dayfirst=True,errors='coerce').dt.date
            def _ui_time(v):
                import datetime as _dt
                if v is None or (isinstance(v,float) and pd.isna(v)) or (isinstance(v,str) and not v.strip()):
                    return None
                if isinstance(v,_dt.time):
                    return v
                if isinstance(v,(_dt.datetime,pd.Timestamp)):
                    return v.time()
                t=pd.to_datetime(str(v),errors='coerce')
                return None if pd.isna(t) else t.time()
            # V11.14: horários são transportados no editor como texto HH:MM:SS.
            # Isso elimina a incompatibilidade TimeColumn x STRING do Streamlit.
            # recalcular_grade() já normaliza texto/time/datetime antes de processar().
            def _ui_time_text(v):
                t=_ui_time(v)
                return '' if t is None else t.strftime('%H:%M:%S')
            exib['Hora Início']=exib['Hora Início'].map(_ui_time_text).astype(str)
            exib['Hora Fim']=exib['Hora Fim'].map(_ui_time_text).astype(str)

            edit=st.data_editor(exib,use_container_width=True,hide_index=True,num_rows='fixed',
                disabled=['linha_origem','OS','Cliente','Técnico','Data Original','Hora Início Original','Hora Fim Original','Tipo Original','Deslocamento','Total','Situação','Pendência','Ação necessária'],
                column_config={
                    'Ação necessária':st.column_config.TextColumn(help='O que deve ser feito para liberar esta OS'),
                    'Pendência':st.column_config.TextColumn(help='Motivo que bloqueou o cálculo'),
                    'Tipo para Pagamento':st.column_config.SelectboxColumn(label='Tipo para Pagamento — EDITÁVEL',options=tipos,help='Selecione a classificação correta'),
                    'Data':st.column_config.DateColumn(label='Data — EDITÁVEL',format='DD/MM/YYYY'),
                    'Hora Início':st.column_config.TextColumn(label='Hora Início — EDITÁVEL',help='Informe HH:MM ou HH:MM:SS'),
                    'Hora Fim':st.column_config.TextColumn(label='Hora Fim — EDITÁVEL',help='Informe HH:MM ou HH:MM:SS'),
                    'KM':st.column_config.NumberColumn(min_value=0.0,step=1.0,format='%.1f'),
                    'Deslocamento':st.column_config.NumberColumn(format='R$ %.2f'),
                    'Pedágio':st.column_config.NumberColumn(min_value=0.0,step=0.01,format='R$ %.2f'),
                    'Outros':st.column_config.NumberColumn(step=0.01,format='R$ %.2f'),
                    'Mão de Obra':st.column_config.NumberColumn(label='Mão de Obra — EDITÁVEL PARA VALOR FECHADO',min_value=0.0,step=0.01,format='R$ %.2f',help='Edite manualmente somente para (MAN) M.O VALOR FECHADO.'),
                    'Total':st.column_config.NumberColumn(format='R$ %.2f')},
                key='editor_grade_v107')
            st.caption(f'Deslocamento: KM × R$ {VALOR_KM:.2f}. Para (MAN) M.O VALOR FECHADO, informe o valor em Mão de Obra e a justificativa. Depois clique em RECALCULAR E VALIDAR.')
            if st.button('RECALCULAR E VALIDAR',type='primary',use_container_width=True,key='recalc_v107'):
                # V11.18: identifica alterações comparando o retorno do editor com o
                # DataFrame EXATO que foi entregue a ele. Não compara com a planilha
                # original nem usa Status=AJUSTADO como proxy de edição humana.
                # Assim, conversões internas não geram justificativas falsas.
                _linhas_editadas = linhas_editadas_usuario(exib, edit)
                full=grade.set_index('linha_origem')
                for _,er in edit.iterrows():
                    li=int(er['linha_origem'])
                    for c in ['Data','Hora Início','Hora Fim','Tipo para Pagamento','KM','Pedágio','Outros','Justificativa']:
                        full.at[li,c]=er[c]
                    if 'Mão de Obra' in er.index:
                        full.at[li,'Mão de Obra']=er['Mão de Obra']
                full=full.reset_index()
                st.session_state['grade_edicoes_v117']=full.copy()

                # Recalcula primeiro com os valores exatamente como saíram do editor.
                nd,np=recalcular_grade(man_src,mapa_src,param_src,full,
                    st.session_state.get('fonte_hc_ini_v107',time(8,0)),
                    st.session_state.get('fonte_hc_fim_v107',time(18,0)),
                    st.session_state.get('fonte_feriados_v107',[]),
                    st.session_state.get('fonte_virada_v107',True))

                # Justificativa é conferida pela linha real editada e somente quando
                # o recálculo classificou a linha como AJUSTADA.
                _just_por_linha={}
                for _,rr in full.iterrows():
                    _j=rr.get('Justificativa','')
                    just=str(_j).strip() if not pd.isna(_j) else ''
                    _just_por_linha[int(rr['linha_origem'])]=just
                falt=[]
                for _ix,rr in nd.iterrows():
                    _li=int(rr.get('linha_origem',0) or 0)
                    just=_just_por_linha.get(_li,'')
                    # A justificativa informada no editor é sempre persistida.
                    # Isso permite regularizar ajustes VALOR MANUAL já existentes,
                    # mesmo quando a única edição necessária é a própria justificativa.
                    if just:
                        nd.at[_ix,'Justificativa Ajuste']=just
                    origem_resultante=str(rr.get('Origem do Valor','AUTOMÁTICO')).upper()
                    if origem_resultante!='AUTOMÁTICO' and not str(nd.at[_ix,'Justificativa Ajuste'] if 'Justificativa Ajuste' in nd.columns else '').strip():
                        falt.append(str(rr.get('OS','')))
                if falt:
                    st.error('Informe a justificativa nas OS realmente alteradas: '+', '.join(falt[:12])+('...' if len(falt)>12 else ''))
                else:
                    # Reexecuta a mesma conferência oficial usada no processamento inicial.
                    # O total operacional deve permanecer o da fonte original para que a
                    # reconciliação continue válida após correções na grade.
                    _fonte = st.session_state.get('fonte_man_v107')
                    _total_operacional = len(_fonte) if isinstance(_fonte, pd.DataFrame) else (len(nd) + len(np))
                    nconf=executar_conferencias(nd, np, _total_operacional)
                    apid=st.session_state.get('apuracao_id')
                    if apid:
                        substituir_revisao(apid,nd,np,nconf,
                            st.session_state.get('aprovador_v7','Rodrigo Santos'),det_atual)
                    elif len(nd):
                        # Apuração originalmente 100% pendente: cria o histórico somente
                        # depois que ao menos uma linha for corrigida/processada.
                        datas_validas=pd.to_datetime(nd.get('Data',pd.Series(dtype='datetime64[ns]')),errors='coerce').dropna()
                        comp=datas_validas.max().strftime('%m/%Y') if len(datas_validas) else data_fim.strftime('%m/%Y')
                        apid=salvar_apuracao(
                            nd,np,nconf,
                            arquivo_origem=st.session_state.get('arquivo_original_nome','relatorio.xlsx'),
                            competencia=comp,
                            arquivo_original_bytes=st.session_state.get('arquivo_original_bytes'))
                        st.session_state['apuracao_id']=apid
                    st.session_state['det']=nd
                    st.session_state['pend']=np
                    st.session_state['conferencia']=nconf
                    st.session_state.pop('integridade_hash',None); st.session_state.pop('integridade_ok',None)
                    st.success(f'Recalculado. Processadas: {len(nd)} • Pendências: {len(np)} • Total: {moeda(nd["Valor Total"].sum() if len(nd) else 0)}')
                    st.rerun()

        st.markdown('<div class="section-title">Detalhamento para revisão</div>', unsafe_allow_html=True)
        st.dataframe(det_filtrado, use_container_width=True, hide_index=True, column_config={'Valor Total':st.column_config.NumberColumn(format='R$ %.2f')})

        st.markdown('<div class="section-title">Checklist de Integridade</div>', unsafe_allow_html=True)
        historico_aprovado = carregar_detalhes_aprovados()
        # Usa o mesmo snapshot persistido que será revalidado ao clicar em Aprovar.
        ap_id_integridade = st.session_state.get('apuracao_id')
        if ap_id_integridade:
            try:
                integridade, _det_persistido = validar_aprovacao_persistida(ap_id_integridade)
            except Exception:
                integridade = checklist_integridade(det_atual, pend_atual, historico_aprovado)
        else:
            integridade = checklist_integridade(det_atual, pend_atual, historico_aprovado)
        for chk in integridade['checks']:
            st.markdown(
                f"<div class={'status-ok' if chk['ok'] else 'status-bad'}>"
                f"{'✅' if chk['ok'] else '⛔'} <b>{chk['nome']}</b> — {chk['detalhe']}</div>"
                "<div style='height:6px'></div>",
                unsafe_allow_html=True
            )
        st.session_state['integridade_hash'] = integridade['hash_detalhes']
        st.session_state['integridade_ok'] = integridade['ok']
        if integridade['ok']:
            st.success(f"Integridade validada • Tabela oficial {integridade['tabela_versao']}.")
        else:
            st.error('APROVAÇÃO BLOQUEADA — corrija as validações de integridade indicadas acima.')

        hist_status = listar_apuracoes()
        ap_id = st.session_state.get('apuracao_id')
        ap_row = hist_status[hist_status['id'].astype(str) == str(ap_id)] if ap_id and not hist_status.empty else pd.DataFrame()
        ja_aprovada = not ap_row.empty and str(ap_row.iloc[0].get('status','')).upper() == 'APROVADA'
        if ja_aprovada:
            st.success(f"✓ PAGAMENTO APROVADO — {ap_row.iloc[0].get('aprovado_por','')} — {ap_row.iloc[0].get('aprovado_em','')}")
        else:
            aprovador = st.text_input('Responsável pela aprovação', value='Rodrigo Santos', key='aprovador_v7')
            pode_aprovar = bool(conf and conf['aprovavel'] and integridade['ok'] and aprovador.strip())
            st.button('APROVAR PAGAMENTO', disabled=not pode_aprovar, type='primary' if pode_aprovar else 'secondary', use_container_width=True, key='btn_aprovar_v102', on_click=None)
            if not pode_aprovar:
                st.caption('A aprovação permanece bloqueada enquanto existir falha crítica ou responsável não informado.')
            elif st.session_state.get('btn_aprovar_v102'):
                try:
                    if not revalidar_hash(det_atual, st.session_state.get('integridade_hash','')):
                        raise ValueError('Os dados foram alterados após a conferência. Recalcule e valide novamente antes de aprovar.')
                    aprovar_apuracao(ap_id, aprovador)
                    st.rerun()
                except Exception as exc:
                    st.error(str(exc))

