                st.markdown('<div class="section-title">Top clientes no plantão</div>', unsafe_allow_html=True)
                pc=p.groupby('Cliente',as_index=False).agg(Atendimentos=('OS','count'),Horas=('Tempo minutos',lambda x: round(pd.to_numeric(x,errors='coerce').sum()/60,1)),Valor=('Valor Total','sum')).sort_values('Valor',ascending=False)
                st.dataframe(pc.head(10),use_container_width=True,hide_index=True,column_config={'Valor':st.column_config.NumberColumn(format='R$ %.2f')})
