                    ph['tempo_minutos']=pd.to_numeric(ph['tempo_minutos'],errors='coerce').fillna(0)
                    mensal=ph.groupby('competencia',as_index=False).agg(Acionamentos=('id','count'),Horas=('tempo_minutos',lambda x:round(x.sum()/60,1)),Custo=('valor_total','sum'))
                    st.markdown('<div class="section-title">Evolução do plantão</div>', unsafe_allow_html=True)
